import{_ as a,o as t,c as r,a2 as d}from"./chunks/framework.DYYBR_aZ.js";const p=JSON.parse('{"title":"harness和learn-claude-code项目","description":"","frontmatter":{},"headers":[],"relativePath":"tools/harness和learn-claude-code项目.md","filePath":"tools/harness和learn-claude-code项目.md"}'),l={name:"tools/harness和learn-claude-code项目.md"};function o(s,e,n,h,c,i){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="harness和learn-claude-code项目" tabindex="-1">harness和learn-claude-code项目 <a class="header-anchor" href="#harness和learn-claude-code项目" aria-label="Permalink to &quot;harness和learn-claude-code项目&quot;">​</a></h1><h2 id="llm-agent-harness" tabindex="-1">llm,agent,harness <a class="header-anchor" href="#llm-agent-harness" aria-label="Permalink to &quot;llm,agent,harness&quot;">​</a></h2><p>1、LLM 只是大脑，</p><p>2、而 Agent 是“大脑 + 自主决策闭环”。</p><p>3、Harness 原意是“马具”或“挽具”，在这里指“驾驭 AI 的基础设施”。</p><p>如果没有 Harness，LLM 只是一个在真空中思考的“大脑”</p><p>如果把 Agent（模型）比作一匹千里马（或赛车手），Harness 就是套在它身上的马具（或赛车本身）。它是为了让模型在特定领域（如编程、农业、酒店管理）能够实际工作而编写的所有外围代码和系统。</p><p>Harness 包含了模型工作所需的一切：</p><ul><li><strong>Tools（工具）：</strong> 给模型一双手。比如文件读写、Shell 执行、API 调用。</li><li><strong>Knowledge（知识）：</strong> 给模型领域专长。比如产品文档、API 规范。</li><li><strong>Observation（观察）：</strong> 给模型眼睛。比如让它看到 <code>git diff</code> 的结果、错误日志。</li><li><strong>Permissions（权限）：</strong> 给模型边界。比如沙箱隔离，防止它删库跑路。</li></ul><h2 id="claude-code的-放权" tabindex="-1">Claude Code的“放权“ <a class="header-anchor" href="#claude-code的-放权" aria-label="Permalink to &quot;Claude Code的“放权“&quot;">​</a></h2><h3 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h3><p>Claude Code 之所以强大，不是因为它用的模型比别人聪明，而是因为它构建的“工作环境”（Harness）最懂如何“放权”和“赋能”。</p><h3 id="最好的-harness-是-隐形-的-做减法" tabindex="-1">最好的 Harness 是“隐形”的（做减法） <a class="header-anchor" href="#最好的-harness-是-隐形-的-做减法" aria-label="Permalink to &quot;最好的 Harness 是“隐形”的（做减法）&quot;">​</a></h3><p>Claude Code 的成功在于它**“没做”**什么。</p><ul><li><strong>错误做法</strong>：很多开发者试图用代码写死工作流（比如：第一步必须干嘛，第二步必须干嘛），或者用复杂的决策树去限制模型。这相当于给赛车手（模型）绑上了绳子，限制了他的发挥。</li><li><strong>Claude Code 的做法</strong>：它**“让开了”**。它不教模型怎么思考，而是提供一套完美的工具和环境，然后信任模型去决策。</li><li><strong>结论</strong>：Harness 的职责是<strong>提供能力</strong>，而不是<strong>限制思维</strong>。</li></ul><h3 id="claude-code-的本质公式" tabindex="-1">Claude Code 的本质公式 <a class="header-anchor" href="#claude-code-的本质公式" aria-label="Permalink to &quot;Claude Code 的本质公式&quot;">​</a></h3><p>Claude Code = 模型 (大脑) + 12种 Harness 机制 (身体/环境)</p><p>重点在于： 这些全是工程代码（Harness），而不是模型训练。这证明了95% 的工作量在于构建这个环境，而非模型本身。</p><table tabindex="0"><thead><tr><th>原文术语</th><th>翻译与解释</th><th>作用</th></tr></thead><tbody><tr><td>Agent Loop</td><td>核心循环</td><td>模型不断“思考-行动-观察”的发动机。</td></tr><tr><td>Tools</td><td>工具箱</td><td>Bash、读写文件等，给模型动手能力。</td></tr><tr><td>按需 Skill 加载</td><td>技能包</td><td>只有需要时才给模型看文档，防止信息过载。</td></tr><tr><td>上下文压缩</td><td>记忆管理</td><td>对话太长时自动总结，腾出空间给新任务。</td></tr><tr><td>子 Agent 派生</td><td>分身/外包</td><td>遇到复杂任务，主模型可以叫“小弟”去干，互不干扰。</td></tr><tr><td>Worktree 隔离</td><td>沙箱环境</td><td>在独立的文件夹里干活，防止把主项目搞挂了。</td></tr><tr><td>权限治理</td><td>安全锁</td><td>规定哪些命令能跑，哪些需要用户确认。</td></tr></tbody></table><h3 id="learn-claude-code分享" tabindex="-1">learn-claude-code分享 <a class="header-anchor" href="#learn-claude-code分享" aria-label="Permalink to &quot;learn-claude-code分享&quot;">​</a></h3><p><a href="https://github.com/shareAI-lab/learn-claude-code/tree/main" target="_blank" rel="noreferrer">https://github.com/shareAI-lab/learn-claude-code/tree/main</a></p><p>它会教你搭建任何agent的harness技巧；</p><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3>',23)])])}const g=a(l,[["render",o]]);export{p as __pageData,g as default};
